using MediatR; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Exceptions; namespace JTradeERP.Application.Features.MasterData.UnitsOfMeasure.DeleteUnitOfMeasure; public sealed class DeleteUnitOfMeasureHandler(IApplicationDbContext db):IRequestHandler<DeleteUnitOfMeasureCommand>{public async Task Handle(DeleteUnitOfMeasureCommand r,CancellationToken ct){var e=db.UnitsOfMeasure.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Unit of Measure not found.");if(db.Products.Any(x=>x.StockUomId==r.Id))throw new ConflictException("Unit of Measure is referenced by a Product.");db.Remove(e);await db.SaveChangesAsync(ct);}}
